import { claim, policyFor, type ClaimResult, type Incident, type Policy } from "./claimSettlement.js";
import { quote, type Customer, type QuoteItem, type QuoteResult } from "./premium.js";

export type { ClaimResult, Damage, Incident } from "./claimSettlement.js";
export type { Customer, QuoteItem, QuoteResult } from "./premium.js";

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = QuoteResult | ClaimResult;

function isFollowUpContract(stepIndex: number): boolean {
  return stepIndex > 0;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex): StepResult => {
    if (step.op === "claim") {
      return claim(step.incident, policies.get(step.policy) as Policy);
    }
    policies.set(stepIndex, policyFor(step.items));
    return quote(step.items, scenario.customer, isFollowUpContract(stepIndex));
  });
  return { results };
}
import { COMPONENT_PRICE, isComponentType, isListedType, isMainItemType, priceOf } from "./priceList.js";

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;
const CURSE_SURCHARGE_PERCENT = 50;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: QuoteItem): boolean {
  return isComponentType(item.type);
}

function isMainItem(item: QuoteItem): boolean {
  return isMainItemType(item.type);
}

function mainItemsOf(items: QuoteItem[]): QuoteItem[] {
  return items.filter(isMainItem);
}

function mainItemBasePremiumOf(mainItem: QuoteItem): number {
  return priceOf(mainItem.type).basePremium;
}

function mainItemsBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + mainItemBasePremiumOf(mainItem), 0);
}

function alikenessOf(component: QuoteItem): string {
  return component.type;
}

function alikeComponentCountsOf(items: QuoteItem[]): number[] {
  const countsByAlikeness = new Map<string, number>();
  for (const alikeness of items.filter(isComponent).map(alikenessOf)) {
    countsByAlikeness.set(alikeness, (countsByAlikeness.get(alikeness) ?? 0) + 1);
  }
  return [...countsByAlikeness.values()];
}

function isBuildingBlock(alikeComponentCount: number): boolean {
  return alikeComponentCount === BLOCK_SIZE;
}

function alikeComponentsBasePremiumOf(count: number): number {
  return isBuildingBlock(count) ? BLOCK_BASE_PREMIUM : count * COMPONENT_PRICE.basePremium;
}

function componentsBasePremiumOf(items: QuoteItem[]): number {
  return alikeComponentCountsOf(items).reduce((sum, count) => sum + alikeComponentsBasePremiumOf(count), 0);
}

function policyBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsBasePremiumOf(items) + componentsBasePremiumOf(items);
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function firstInsuranceSurchargeOn(policyBasePremium: number): number {
  return percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
}

function premiumRoundedInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function isHighlyEnchanted(mainItem: QuoteItem): boolean {
  return (mainItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
}

function curseSurchargePercentOf(mainItem: QuoteItem): number {
  return mainItem.cursed ? CURSE_SURCHARGE_PERCENT : 0;
}

function highEnchantmentSurchargePercentOf(mainItem: QuoteItem): number {
  return isHighlyEnchanted(mainItem) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
}

function riskSurchargePercentOf(mainItem: QuoteItem): number {
  return curseSurchargePercentOf(mainItem) + highEnchantmentSurchargePercentOf(mainItem);
}

function riskSurchargeOn(mainItem: QuoteItem): number {
  return percentOf(mainItemBasePremiumOf(mainItem), riskSurchargePercentOf(mainItem));
}

function riskSurchargesOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + riskSurchargeOn(mainItem), 0);
}

function isLoyalCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscountOn(policyBasePremium: number, customer: Customer): number {
  return isLoyalCustomer(customer) ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT) : 0;
}

function followUpContractDiscountOn(policyBasePremium: number, isFollowUpContract: boolean): number {
  return isFollowUpContract ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
}

function policyWideModifiersOn(policyBasePremium: number, customer: Customer, isFollowUpContract: boolean): number {
  return (
    firstInsuranceSurchargeOn(policyBasePremium) -
    loyaltyDiscountOn(policyBasePremium, customer) -
    followUpContractDiscountOn(policyBasePremium, isFollowUpContract)
  );
}

function assertInsurable(item: QuoteItem): void {
  if (!isListedType(item.type)) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
}

export function quote(items: QuoteItem[], customer: Customer, isFollowUpContract: boolean): QuoteResult {
  items.forEach(assertInsurable);
  const policyBasePremium = policyBasePremiumOf(items);
  const unroundedPremium =
    policyBasePremium +
    riskSurchargesOf(items) +
    policyWideModifiersOn(policyBasePremium, customer, isFollowUpContract) +
    PROCESSING_FEE;
  return { premium: premiumRoundedInMHPCOsFavor(unroundedPremium) };
}
interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };

export function isMainItemType(type: string): boolean {
  return type in MAIN_ITEM_PRICE_LIST;
}

export function isComponentType(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}

export function isListedType(type: string): boolean {
  return isMainItemType(type) || isComponentType(type);
}

export function priceOf(type: string): PriceListEntry {
  return isComponentType(type) ? COMPONENT_PRICE : MAIN_ITEM_PRICE_LIST[type];
}
import type { QuoteItem } from "./premium.js";
import { priceOf } from "./priceList.js";
import { reimbursementRateOf } from "./reimbursementClauses.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface Policy {
  insuredItems: QuoteItem[];
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

function insuranceValueOf(item: QuoteItem): number {
  return priceOf(item.type).insuranceValue;
}

function insuranceSumOf(items: QuoteItem[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

export function policyFor(items: QuoteItem[]): Policy {
  return { insuredItems: items, remainingCap: insuranceSumOf(items) * CAP_MULTIPLIER };
}

function damagedItemOf(damage: Damage, policy: Policy): QuoteItem {
  return policy.insuredItems.find((item) => item.type === damage.itemType) as QuoteItem;
}

function reimbursementAfterDeductibleOf(damage: Damage, policy: Policy): number {
  return damage.amount * reimbursementRateOf(damagedItemOf(damage, policy)) - DEDUCTIBLE_PER_DAMAGE;
}

function payoutBeforeCapOf(incident: Incident, policy: Policy): number {
  return incident.damages.reduce((sum, damage) => sum + reimbursementAfterDeductibleOf(damage, policy), 0);
}

function payoutRoundedInMHPCOsFavor(payout: number): number {
  return Math.floor(payout);
}

export function claim(incident: Incident, policy: Policy): ClaimResult {
  const payout = payoutRoundedInMHPCOsFavor(Math.min(payoutBeforeCapOf(incident, policy), policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
import type { QuoteItem } from "./premium.js";

const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

function isCoveredByHighEnchantmentClause(damagedItem: QuoteItem): boolean {
  return (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
}

export function reimbursementRateOf(damagedItem: QuoteItem): number {
  return isCoveredByHighEnchantmentClause(damagedItem)
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : FULL_REIMBURSEMENT_RATE;
}
